package com.mytransitgps.modules.ciq.collector;
import com.mytransitgps.modules.ciq.client.LtaRoadWorksClient;import com.mytransitgps.modules.ciq.config.CiqProperties;import com.mytransitgps.modules.ciq.domain.RoadWorkRecord;import com.mytransitgps.modules.ciq.parser.RoadWorksParser;import com.mytransitgps.modules.ciq.persistence.*;import com.mytransitgps.modules.ciq.quality.RoadWorksValidator;import com.mytransitgps.modules.ciq.storage.*;import com.mytransitgps.platform.collection.*;import org.slf4j.*;
/** API06 独立 Collector。 */
public class CiqRoadWorksCollector implements DataCollector {private static final Logger log=LoggerFactory.getLogger(CiqRoadWorksCollector.class);private final CiqPagedJsonCollectorSupport<RoadWorkRecord> support;public CiqRoadWorksCollector(LtaRoadWorksClient client,CiqProperties p,CiqJsonStorageService storage,RoadWorksParser parser,RoadWorksValidator validator,RoadWorksPersistenceService persistence,CiqAuditPersistenceService audit){support=new CiqPagedJsonCollectorSupport<>("API06",CiqApiCode.API06,CollectorCode.CIQ_ROAD_WORKS,client,p,p.getCollectors().getRoadWorks(),storage,parser::parse,validator::isValid,persistence==null?null:persistence::persist,audit,log);}public ModuleCode moduleCode(){return ModuleCode.CIQ;}public CollectorCode collectorCode(){return CollectorCode.CIQ_ROAD_WORKS;}public CollectionResult collect(CollectionContext c){return support.collect(c);}}
